// This node checks if transcript needs chunking
const items = $input.all();
const output = [];

for (const item of items) {
  const transcript = item.json.Transcript || '';
  const transcriptLength = transcript.length;
  const MAX_DIRECT_CHARS = 10000; // ~7500 tokens

  output.push({
    json: {
      ...item.json,
      needsChunking: transcriptLength > MAX_DIRECT_CHARS,
      transcriptLength: transcriptLength,
      // Keep original for routing
      transcript: transcript
    }
  });
}

return output;

// Split transcript into overlapping chunks
const items = $input.all();
const output = [];

const CHUNK_SIZE = 2000; // words per chunk
const OVERLAP = 500; // word overlap between chunks

for (const item of items) {
  const transcript = item.json.Transcript || '';
  const words = transcript.split(/\s+/);

  // Create chunks with overlap
  const chunks = [];
  for (let i = 0; i < words.length; i += CHUNK_SIZE) {
    const chunk = words.slice(i, i + CHUNK_SIZE + OVERLAP).join(' ');
    chunks.push(chunk);
  }

  // Output one item per chunk
  chunks.forEach((chunk, index) => {
    output.push({
      json: {
        video_title: item.json.video_title,
        video_url: item.json.video_url,
        topic: item.json.topic,
        genre: item.json.genre,
        chunkText: chunk,
        chunkNumber: index + 1,
        totalChunks: chunks.length,
        // Store for later aggregation
        originalItemIndex: item.json.id || 0
      }
    });
  });
}

return output;

