// Max characters allowed for transcript
const MAX_CHARS = 5000;

// Get all incoming items
const items = $input.all();

return items.map(item => {
  const transcript = item.json.Transcript || "";

  // If transcript is already small enough
  if (transcript.length <= MAX_CHARS) {
    return {
      json: {
        ...item.json,
        truncatedTranscript: transcript,
        wasTruncated: false,
        originalLength: transcript.length,
      }
    };
  }

  // Split strategy: start + middle + end
  const chunkSize = Math.floor(MAX_CHARS / 3);

  const start = transcript.slice(0, chunkSize);
  const middleStart = Math.max(
    Math.floor(transcript.length / 2 - chunkSize / 2),
    0
  );
  const middle = transcript.slice(middleStart, middleStart + chunkSize);
  const end = transcript.slice(transcript.length - chunkSize);

  const truncatedTranscript = `[START]
${start}

[MIDDLE]
${middle}

[END]
${end}`;

  return {
    json: {
      truncatedTranscript,
      wasTruncated: true,
      originalLength: transcript.length,
    }
  };
});

